  const saved=JSON.parse(safeStorage.get()||'null');
  const initial={preset:'US-00',intensity:.55,ambientStrength:.42,surfaceTint:.28,accentUsage:.34,effects:true,...(saved||{})};
  if(PRESETS.some(p=>p.id===initial.preset)) engine.setPalette(initial.preset);
  engine.setOptions(initial);
  function strip(p){return `<div class="palette-strip">${p.colors.map(c=>`<i style="background:${c}"></i>`).join('')}</div>`}
  function renderGrid(){grid.innerHTML=PRESETS.map(p=>`<button class="palette-option ${engine.getPalette().id===p.id?'active':''}" data-palette-id="${p.id}">${strip(p)}<div class="palette-name"><span>${p.id} · ${p.name}</span><span>${p.labelZh||''}</span></div></button>`).join('');grid.querySelectorAll('[data-palette-id]').forEach(b=>b.onclick=()=>{engine.setPalette(b.dataset.paletteId);persist();renderGrid();})}
  const customDefault=['#0A1335','#163B7A','#4B70BE','#C89A55','#F2D79E'];
  document.getElementById('customGrid').innerHTML=customDefault.map((c,i)=>`<input type="color" id="custom${i}" value="${c}">`).join('');
  const controls={intensity:'intensity',ambient:'ambientStrength',surfaceTint:'surfaceTint',accentUsage:'accentUsage'};
  Object.entries(controls).forEach(([id,key])=>{const el=document.getElementById(id),v=document.getElementById(id+'V');el.value=Math.round(initial[key]*100);v.textContent=el.value;el.oninput=()=>{v.textContent=el.value;engine.setOptions({[key]:Number(el.value)/100});persist();}});
  const effects=document.getElementById('effects');effects.checked=initial.effects!==false;effects.onchange=()=>{engine.setOptions({effects:effects.checked});persist();};
  document.getElementById('applyCustom').onclick=()=>{engine.setCustomPalette([0,1,2,3,4].map(i=>document.getElementById('custom'+i).value));persist();renderGrid();};
  document.getElementById('resetPreset').onclick=()=>{engine.setPalette('US-00');engine.setOptions({intensity:.55,ambientStrength:.42,surfaceTint:.28,accentUsage:.34,effects:true});['intensity','ambient','surfaceTint','accentUsage'].forEach((id,i)=>{const vals=[55,42,28,34];document.getElementById(id).value=vals[i];document.getElementById(id+'V').textContent=vals[i]});effects.checked=true;persist();renderGrid();};
